def run_case_object_array_control():
    # PR report: np.histogram([np.array(0.5) for i in range(10)] + [.500000000000002]) should not crash
    arrs = [np.array(0.5) for i in range(10)]
    x = arrs + [0.500000000000002]
    try:
        counts, lims = np.histogram(x)
        return {
            'exception': False,
            'counts': counts,
            'lims': lims,
        }
    except Exception as e:
        return {
            'exception': True,
            'exception_type': type(e).__name__,
            'exception_msg': str(e),
        }

out_small = run_case_small_value_range()
out_ctrl = run_case_object_array_control()

