    probe('small_value_range_exception_msg_len', float(len(out_small.get('exception_msg',''))))

probe('object_array_control_exception', float(out_ctrl['exception']))
if not out_ctrl['exception']:
    probe('object_array_control_counts', out_ctrl['counts'])
    probe('object_array_control_lims', out_ctrl['lims'])
else:
    probe('object_array_control_exception_msg_len', float(len(out_ctrl.get('exception_msg',''))))

